/**	
 * 
 * 1. 설 명
 *    파라미터로 들어온 Key값을 이용하여 해당 Message를 출력한다.
 *
 * 2. 특이사항
 *    key와 일치하는 값이 없을 경우 해당 key값을 리턴한다.
 * 
 * <b>Parameters</b>
 *    key : 해당 메세지를 출력하기 위한 key값.
 *    targetMsg : key에 포함시킬 메세지
 * 
 * <b>return</b>
 *    content : 해당 메세지를 조합한  후 얻은 결과값.
 *
 * [[사용예]]
 *  => alert( getMessageParam("MSG-0001", "개인정보수정") );
 */
/**
 * @method
 * @name getMessageParam
 * @description desc
 * @param {string} key desc
 * @param {string} targetMsg desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getMessageParam = function(key, targetMsg) {
    var flag = false;
    var content;
    for (i = 0; i < messageKeys.length; i++) {
        if (key == messageKeys[i].key) {
            content = messageKeys[i].content;
            flag = true;
            break;
        }
    }
    if (content == undefined) content = "MessageCode: " + key;
    if (flag == false) content = "MessageCode: " + key;
    var count = content.indexOf("^");
    if (count > -1) {
        content = content.substring(0, count) + targetMsg + content.substring(count + 1);
    }
    return content;
};




/*
	2008.01.17 김성일
	id로 넘겨받은 obj를 화면상에 표시하거나 숨기는 함수 flag가 false일 때 숨기고 true일 때 표시함.
*/
/**
 * @method
 * @name showObj
 * @description desc
 * @param {string} ObjID desc
 * @param {string} flag desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.showObj = function(ObjID, flag) {
    // flag = true 표시, flag = false 표시안함
    //	ObjID.Visiable = flag;
    ObjID.style.display = (flag == true) ? "" : "none";
};

/*
	2008.01.17 김성일
	id로 넘겨받은 obj의 위치를 변경할 때 사용함.
*/
/**
 * @method
 * @name SetWindowPos
 * @description desc
 * @param {string} ObjID desc
 * @param {string} nTop desc
 * @param {string} nLeft desc
 * @param {string} nWidth desc
 * @param {string} nHeight desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.SetWindowPos = function(ObjID, nTop, nLeft, nWidth, nHeight) {
    ObjID.style.top = nTop;
    ObjID.style.left = nLeft;
    ObjID.style.setGridWidth(nWidth);
    ObjID.style.setGridHeight(nHeight);
};
/**
 * @method
 * @name SetWindowPos2
 * @description desc
 * @param {string} ObjID desc
 * @param {string} nLeft desc
 * @param {string} nTop desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.SetWindowPos2 = function(ObjID, nLeft, nTop) {
    ObjID.style.left = nLeft;
    ObjID.style.top = nTop;
};



/**
	2008.01.17 김성일
	목록에서 조회창을 새창으로 띄울 경우, 부모창의 중앙으로 새창을 옮기는 기능.
	child onload에서 사용할 수 있음.
*/
/**
 * @method
 * @name MoveCenterOfParent
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.MoveCenterOfParent = function() {
    var parentWin = $c.frame.path("../");
    var selfWin = $c.frame.path("./");
    var nX = parentWin.XPos;
    var nY = parentWin.YPos;
    var nWidth = parentWin.Width;
    var nHeight = parentWin.Height;
    var selfWidth = selfWin.Width;
    var selfHeight = selfWin.Height;

    //alert("nX=" + nX + ",nY=" + nY + ",nWidth=" + nWidth + ",nHeight=" + nHeight);
    selfWin.XPos = (nWidth / 2) - (selfWidth / 2);
    selfWin.YPos = (nHeight / 2) - (selfHeight / 4);
};

/*
	2008.01.17 김성일
	id로 넘겨받은 obj에 담긴 에러 메세지를 alert 시킴.
*/
/**
 * @method
 * @name alert_error
 * @description desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.alert_error = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK");
    for (var i = 0; i < USER_DEFINE.length; i++) {
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {
            alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
        }
    }
};





