/*
	2008.01.17 김성일
	id로 넘겨받은 obj의 type과 naming rule에 따라 IF을 각각 호출하여 값을 가져옴.
*/
/**
 * @method
 * @name getObjectValue
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getObjectValue = function(obj) {
    // type으로 알수 있는 것은 text랑 checkbox 밖에 없음. 이건 html ctrl을 그대로 사용한 것으로 보임.
    if (obj.type == "text") {
        return scwin.trim(obj.getValue());
    } else if (obj.type == "checkbox") {
        return (obj.checked) ? "Y" : "N";
    } else if (obj.type == "password") {
        return scwin.trim(obj.getValue());
    }
    // 나머진 Naming 으로 판단함.	
    else if (obj.id.indexOf("rdo") > -1) {
        // radio = CodeValue
        return obj.getValue();
    } else if (obj.id.indexOf("edt") > -1) {
        // emedit = text
        return scwin.trim(obj.getText());
    } else if (obj.id.indexOf("cmb") > -1) {
        // combo = cmb_Tab1_Dep.ValueOfIndex("VALUE", cmb_Tab1_Dep.Index);
        var tmp = obj.ValueOfIndex("VALUE", obj.getSelectedIndex());
        if (tmp.indexOf("null") > -1) {
            return "";
        }
        return obj.ValueOfIndex("VALUE", obj.getSelectedIndex());
    } else if (obj.id.indexOf("txa") > -1) {
        // textarea = text
        return scwin.trim(obj.getText());
    }
    return ("");
};

/*
	2008.01.17 김성일
	id로 넘겨받은 obj의 type과 naming rule에 따라 IF을 각각 호출하여 값을 넣는다.
*/
/**
 * @method
 * @name setObjectValue
 * @description desc
 * @param {string} obj desc
 * @param {string} value desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setObjectValue = function(obj, value) {
    // type으로 알수 있는 것은 text랑 checkbox 밖에 없음. 이건 html ctrl을 그대로 사용한 것으로 보임.
    if (obj.type == "text") {
        obj.setValue(value.getValue());
    } else if (obj.type == "checkbox") {
        obj.setValue((value == "Y") ? true : false);
    }
    // 나머진 Naming 으로 판단함.	
    else if (obj.id.indexOf("rdo") > -1) {
        // radio = CodeValue
        obj.setValue(value.getValue());
    } else if (obj.id.indexOf("edt") > -1) {
        // emedit = text
        obj.setValue(value.getValue());
    } else if (obj.id.indexOf("cmb") > -1) {
        // combo = cmb_Tab1_Dep.ValueOfIndex("VALUE", cmb_Tab1_Dep.Index);
        obj.setSelectedIndex(obj.IndexOfColumn("VALUE", value));
    } else if (obj.id.indexOf("txa") > -1) {
        // textarea = text
        obj.setValue(value.getValue());
    }
    return ("");
};

/*
	2008.01.17 김성일
	String의 좌우 공백 제거
*/
/**
 * @method
 * @name trim
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.trim = function(str) {
    if (str == undefined || str == null) return "";
    str += "";
    return str.replace(/(^\s*)|(\s*$)/g, "");
};

/*
	2008.01.17 김성일
	String의 특정 문자열(문자)를 특정문자열(문자)로 바꿈.
*/
/**
 * @method
 * @name replaceAll
 * @description desc
 * @param {string} src_str desc
 * @param {string} src_char desc
 * @param {string} tar_char desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.replaceAll = function(src_str, src_char, tar_char) {
    var reg = new RegExp(src_char, "ig");
    return src_str.replace(reg, tar_char);
};

/*
	2008.01.21 김성일
	넘어온 값에 comma 표시
*/
/**
 * @method
 * @name FormatNumberEx
 * @description desc
 * @param {string} v1 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.FormatNumberEx = function(v1) {
    // FormatNumberEx("3000", 3) return "3,000"
    if (v1 == "") return '';
    var v2 = 3;
    var v3 = "";
    var str = new Array();
    v1 = String(v1);
    if (v1.indexOf(".") > -1) {
        v3 = v1.substring(v1.indexOf("."), v1.length);
        v1 = v1.substring(0, v1.indexOf("."));
    }
    for (var i = 1; i <= v1.length; i++) {
        if (i % v2) {
            str[v1.length - i] = v1.charAt(v1.length - i);
        } else {
            str[v1.length - i] = ',' + v1.charAt(v1.length - i);
        }
    }
    str = str.join('').replace(/^,/, '');
    str = str + v3;
    return str;
};
/**
 * @method
 * @name FormatDateEx
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.FormatDateEx = function(str) {
    if (str == "") return "";
    var yyyy = str.substring(0, 4);
    var mm = str.substring(4, 6);
    var dd = str.substring(6, 8);
    return yyyy + "-" + mm + "-" + dd;
};



/**
 * @type   : function
 * @access : public
 * @desc   : 가우스의 데이터셋 오브젝트 간에 데이터를 복사한다. 복사대상이 되는 데이터셋의 기존의 데이터는 모두 삭제된다.
 *           features 파라미터에서 copyHeader를 yes로 할 경우 DataSet의 컬럼정보까지 복사된다.
 * <pre>
 *    CopyDataSet(oDelivRsltOriginGDS, oDelivRsltCopiedGDS, "copyHeader=no"); 
 * </pre>
 * @sig    : oOriginDataSet, oTargetDataSet[, features]
 * @param  : oOriginDataSet required 원본 DataSet
 * @param  : oTargetDataSet required 복사되어질 DataSet
 * @param  : features       optional 기타 속성을 정의하는 스트링. 속성종류는 아래와 같다.
 * <pre>
 *     copyHeader  : Header를 복사할지 여부. (default:yes) 
 *     resetStatus : 복사된 DataSet의 Status를 reset 할 지 여부. (default:yes)
 *     rowFrom     : 복사할 row의 시작 index. (default:1) 
 *     rowCnt      : 복사할 row의 갯수 index. (default:DataSet.CountRow 의 값) 
 *     사용예) "copyHeader=yes,rowFrom=1,rowCnt=2"  -> 1번 row 부터 3번 row까지 Header와 함께 복사함.
 * </pre>
 */

/**
 * @method
 * @name CopyDataSet
 * @description    가우스의 데이터셋 오브젝트 간에 데이터를 복사한다. 복사대상이 되는 데이터셋의 기존의 데이터는 모두 삭제된다.
 * @param {string} oOriginDataSet desc
 * @param {string} oTargetDataSet desc
 * @param {string} features desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CopyDataSet = function(oOriginDataSet, oTargetDataSet, features) {
    var featureNames = ["copyHeader", "resetStatus", "rowFrom", "rowCnt"];
    var featureValues = [true, true, 1, oOriginDataSet.getTotalRow()];
    var featureTypes = ["boolean", "boolean", "number", "number"];
    if (features != null) {
        scwin.cfParseFeature(features, featureNames, featureValues, featureTypes);
    }
    var copyHeader = featureValues[0];
    var resetStatus = featureValues[1];
    var rowFrom = featureValues[2];
    var rowCnt = featureValues[3];
    if (copyHeader == true) {
        scwin.CopyDataSetHeader(oOriginDataSet, oTargetDataSet);
    }
    oTargetDataSet.ClearData();
    if (oOriginDataSet.getTotalRow() > 0) {
        var temp = oTargetDataSet.dataid; // importdata를 한 후 DataSet의 기존의 dataid 속성값이 지워지는 것을 방지.
        oTargetDataSet.ImportData(oOriginDataSet.ExportData(rowFrom, rowCnt, true));
        oTargetDataSet.dataid = temp;
        if (resetStatus == true) {
            oTargetDataSet.ResetStatus();
        }
    }
};







/**
 * @type   : function
 * @access : public
 * @desc   : 가우스의 데이터셋 오브젝트 간에 컬럼 헤더 정보를 복사한다.
 * <pre>
 *    CopyDataSet(oDelivRsltOriginGDS, oDelivRsltCopiedGDS); 
 * </pre>
 * @sig    : oOriginDataSet, oTargetDataSet
 * @param  : oOriginDataSet required 원본 DataSet
 * @param  : oTargetDataSet required 복사되어질 DataSet
 */

/**
 * @method
 * @name CopyDataSetHeader
 * @description    가우스의 데이터셋 오브젝트 간에 컬럼 헤더 정보를 복사한다.
 * @param {string} oOriginDataSet desc
 * @param {string} oTargetDataSet desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CopyDataSetHeader = function(oOriginDataSet, oTargetDataSet) {
    var DsHeader = "";
    var colId = "";
    var colType = "";
    var colProp = "";
    var colSize = "";
    var colDec = "";
    for (var i = 1; i <= oOriginDataSet.getTotalCol(); i++) {
        colId = oOriginDataSet.ColumnID(i); //column id
        colIndex = oOriginDataSet.ColumnIndex(colId); //column id에 해당하는 index값	
        colSize = oOriginDataSet.ColumnSize(colIndex); //column size
        colDec = oOriginDataSet.ColumnDec(colIndex); //column size

        /* column의 type 정의 코드
        		Type  Description
        		-----------------
        		 1    String 
        		 2    Integer
        		 3    Decimal
        		 4    Date
        		 5    URL
        	*/
        //column type정의
        switch (oOriginDataSet.ColumnType(colIndex)) {
            case 1:
                colType = 'String';
                break;
            case 2:
                colType = 'Integer';
                break;
            case 3:
                colType = 'Decimal';
                break;
            case 4:
                colType = 'Date';
                break;
            case 5:
                colType = 'URL';
                break;
            case 9:
                colType = 'BIGINT';
                break;
            default:
                colType = "";
                break;
        }

        /* column의 property 정의
        	0 : Normal (Key = No)
        	1 : Constant
        	2 : Key (Normal, Sequence)
        	3 : Sequence (Key = No) // 현재 의미없음.
        */

        switch (oOriginDataSet.ColumnProp(i)) {
            case 0:
                colProp = "NORMAL";
                break;
            case 1:
                colProp = "CONSTANT";
                break;
            case 2:
                colProp = "KEYVALUE";
                break;
            default:
                colProp = "";
                break;
        }
        //column id,column type,column size, column property
        if (colType == "Decimal") {
            DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + "." + colDec + ")" + ":" + colProp + ",";
        } else {
            DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + ")" + ":" + colProp + ",";
        }
    }
    DsHeader = DsHeader.substr(0, DsHeader.length - 1);
    oTargetDataSet.SetDataHeader(DsHeader);
};



/**
 * @type   : function
 * @access : private
 * @desc   : features 스트링을 파싱하여 array에 셋팅하는 내부 함수
 * @sig    : features, fNameArray, fValueArray, fTypeArray
 * @param  : features    required features를 표현한 스트링
 * @param  : fNameArray  required 추출해야 할 feature의 이름에 대한 array
 * @param  : fValueArray required 추출해야 할 feature의 기본값에 대한 array 
 * @param  : fTypeArray  required 추출해야 할 feature의 데이터타입에 대한 array 
 */

/**
 * @method
 * @name cfParseFeature
 * @description    features 스트링을 파싱하여 array에 셋팅하는 내부 함수
 * @param {string} features desc
 * @param {string} fNameArray desc
 * @param {string} fValueArray desc
 * @param {string} fTypeArray desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cfParseFeature = function(features, fNameArray, fValueArray, fTypeArray) {
    if (features == null) {
        return;
    }
    var featureArray = features.split(",");
    var featurePair;
    for (var i = 0; i < featureArray.length; i++) {
        featurePair = $c.ut.trim().split("=");
        for (var j = 0; j < fNameArray.length; j++) {
            if (featurePair[0] == fNameArray[j]) {
                switch (fTypeArray[j]) {
                    case "string":
                        fValueArray[j] = featurePair[1];
                        break;
                    case "number":
                        fValueArray[j] = Number(featurePair[1]);
                        break;
                    case "boolean":
                        if (featurePair[1].toUpperCase() == "YES" || featurePair[1].toUpperCase() == "TRUE" || featurePair[1] == "1") {
                            fValueArray[j] = true;
                        } else {
                            fValueArray[j] = false;
                        }
                        break;
                }
            }
        }
    }
};



