/**
 * @method
 * @name alert_parse
 * @description desc
 * @param {string} str desc
 * @param {string} token desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.alert_parse = function(str, token) {
    var arr = str.split(token);
    var msg = "";
    for (var i = 0; i < arr.length; i++) {
        msg += arr[i] + "\n";
    }
    alert(msg);
};


