//공통함수로사용도록 한다.
/*
 * 페이징처리 헤더 생성하기 =>  총건수: 29  페이지: 1/1 [ 1 2  ] 
 */
/**
 * @method
 * @name FillGridHeader2
 * @description desc
 * @param {string} vPageNoCnt desc
 * @param {string} vPageSize desc
 * @param {string} vRsltCnt desc
 * @param {string} panalID desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.FillGridHeader2 = function(vPageNoCnt, vPageSize, vRsltCnt, panalID) {
    vFeatures = "PageLinkCnt=" + vPageSize;
    var vPageNo = 0;
    var vPageCnt = 0;
    var vPageStartLinkNo = 0;
    var vPageEndLinkNo = 0;
    var vPrevBtn = "&nbsp;";
    var vNextBtn = "&nbsp;";
    var vPrevPageSetBtn = "";
    var vNextPageSetBtn = "";
    var vTotalArea = "&nbsp;";
    var vPageInfoArea = "&nbsp;";
    var vPageLinkArea = "&nbsp;";
    var action = "";
    var parameter = "";
    var vFeatureNames = ["width", "showTotal", "showPageInfo", "pageLinkCnt", "showPageBtn"];
    var vFeatureValues = [835, true, true, 10, true];
    var vFeatureTypes = ["number", "boolean", "boolean", "number", "boolean"];
    if (vFeatures != null) {
        scwin.ParseFeature(vFeatures, vFeatureNames, vFeatureValues, vFeatureTypes);
    }
    var vWidth = parseInt(panel_page.style.getStyle("width"), 10);
    var vShowTotal = vFeatureValues[1];
    var vShowPageInfo = vFeatureValues[2];
    var vPageLinkCnt = vFeatureValues[3];
    var vShowPageBtn = vFeatureValues[4];
    vPageLinkCnt = vPageSize;

    // 디자이너의 요구에 의해 페이지 이동 버튼은 표현되지 않음.
    vShowPageBtn = false;
    vPageNo = vCurrPageNo;
    var vTotalPageCnt = 0; //전체 페이지 수(전체 조회수/한페이지에 보여줄 수)

    if (vRsltCnt % vPageLinkCnt > 0) {
        vTotalPageCnt = Math.floor(vRsltCnt / vPageLinkCnt) + 1; //나머지가 있을 경우는 1페이지 더한다.

    } else {
        vTotalPageCnt = Math.floor(vRsltCnt / vPageLinkCnt);
    }
    vPageCnt = vTotalPageCnt;
    if (vShowPageBtn) {
        if (vPageNo > 1) {
            vPrevBtn = "<a style='cursor:hand;' onclick=\"javascript:PageNoCall(" + (vPageNo - 1) + ")\">◀ </a>";
        }
        if (vPageNo < vPageCnt) {
            vNextBtn = "<a style='cursor:hand;' onclick=\"javascript:PageNoCall(" + (vPageNo + 1) + ")\">▶</a>";
        }
    }
    vPageLinkCnt = vPageNoCnt;
    if (!isNaN(vPageLinkCnt) && (vPageLinkCnt != 0) && (vPageNo != 0)) {
        vPageStartLinkNo = Math.floor(Math.abs(vPageNo - 1) / vPageLinkCnt) * vPageLinkCnt + 1;
        if (vPageStartLinkNo == 1) {
            vPrevPageSetBtn = "";
        } else {
            vPrevPageSetBtn = "<a style='font-size__9pt; font-family:굴림; text-decoration:none; color:#212863; cursor:hand;' " + "onclick=\"PageNoCall(" + (vPageStartLinkNo - vPageLinkCnt) + ")\">" + "◀ " + "</a>";
        }
        if ((vPageStartLinkNo + vPageLinkCnt - 1) < vPageCnt) {
            vPageEndLinkNo = vPageStartLinkNo + vPageLinkCnt - 1;
            vNextPageSetBtn = "<a style='font-size__9pt; font-family:굴림; text-decoration:none; color:#212863; cursor:hand;' " + "onclick=\"PageNoCall(" + (vPageStartLinkNo + vPageLinkCnt) + ")\">" + " ▶" + "</a>";
        } else {
            vPageEndLinkNo = vPageCnt;
            vNextPageSetBtn = "";
        }
        vPageLinkArea = vPrevPageSetBtn + "<span style='font-size__9pt; font-family:굴림; color:#212863;'>[</span>";
        for (var i = vPageStartLinkNo; i <= vPageEndLinkNo; i++) {
            if (i != vPageNo) {
                vPageLinkArea = vPageLinkArea + "<a style='font-size__9pt; font-family:굴림; text-decoration:none; color:#212863; cursor:hand;' " + "onclick=\"PageNoCall(" + i + ")\"> " + i + " </a>";
            } else {
                vPageLinkArea = vPageLinkArea + "<span style='font-size__9pt; font-family:굴림; color:#5C8BE0; font-weight:bold;'> " + i + " </span>";
            }
        }
        vPageLinkArea = vPageLinkArea + "<span style='font-size__9pt; font-family:굴림; color:#212863;'>]</span>" + vNextPageSetBtn;
    }
    if (vShowTotal) {
        vTotalArea = "<span style='font-size__9pt; font-family:굴림; color:#212863;'>총건수: </span><span style='font-size__9pt; font-family:굴림; color:#5C8BE0; font-weight:bold'>" + scwin.FormatNumberEx(vRsltCnt) + "</span>";
    }
    if (vShowPageInfo) {
        vPageInfoArea = "<span style='font-size__9pt; font-family:굴림; color:#212863;'>";
        if (vShowTotal == true) {
            vPageInfoArea = vPageInfoArea + "&nbsp;&nbsp;";
        }
        vPageInfoArea = vPageInfoArea + "페이지: </span><span style='font-size__9pt; font-family:굴림; color:#5C8BE0; font-weight:bold;'>" + vPageNo + "/" + vPageCnt + "</span>";
    }
    panalID.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='" + vWidth + "'>" + "    <tr>" + "        <td align='left' width='2%' nowrap>" + vTotalArea + vPageInfoArea + "</td>" + "        <td align='center'>" + vPageLinkArea + "</td>" + "        <td align='right' width='30'>" + vPrevBtn + vNextBtn + "</td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
};

