/*
 * from, to 날짜에 기간구분선택에 따른 날짜 셋팅하기   
 *  - 기간구분 : pTp
 *  - from 객체 이름 : pObjFrom
 *  - to 객체 이름 : pObjTo
 */
/**
 * @method
 * @name fn_setFromToDate
 * @description desc
 * @param {string} pTp desc
 * @param {string} pObjFrom desc
 * @param {string} pObjTo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setFromToDate = function(pTp, pObjFrom, pObjTo) {
    //1주일^1,1개월^2,3개월^3,6개월^4,1년^5,2년^6
    var vFrom = "";
    var vTo = scwin.getObjectValue(pObjTo);
    if (vTo == '') {
        // 값이 없으면 현재일 기준으로 계산
        vTo = $c.ut.cGetToday("yyyymmdd");
    }
    if (pTp == 1) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 7); // 일주일전		

    } else if (pTp == 2) {
        // 1개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 1);
    } else if (pTp == 3) {
        // 3개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 3);
    } else if (pTp == 4) {
        // 6개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 6);
    } else if (pTp == 5) {
        // 1년전
        vFrom = $c.ut.cGetMinusYear(vTo, 1);
    } else if (pTp == 6) {
        // 2년전
        vFrom = $c.ut.cGetMinusYear(vTo, 2);
    }
    scwin.setObjectValue(pObjFrom, vFrom);
    scwin.setObjectValue(pObjTo, vTo);
};


/*
 * from, to 날짜에 기간구분선택에 따른 날짜 셋팅하기
 *  - 기간구분 : pTp (3d, 3m, 3y)
 *  - from 객체 이름 : pObjFrom
 *  - to 객체 이름 : pObjTo
 */
/**
 * @method
 * @name fn_setFromToDate1
 * @description desc
 * @param {string} pTerm desc
 * @param {string} pObjFrom desc
 * @param {string} pObjTo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setFromToDate1 = function(pTerm, pObjFrom, pObjTo) {
    var vFrom = "";
    var vTo = scwin.getObjectValue(pObjTo);
    if (vTo == '') {
        // 값이 없으면 현재일 기준으로 계산
        vTo = $c.ut.cGetToday("yyyymmdd");
    }
    pTerm = pTerm.toLowerCase();
    var nIdx = pTerm.search(/d|m|y/g);
    var sTerm = pTerm.substring(0, nIdx);
    var sTp = pTerm.substring(nIdx, pTerm.length);
    if (sTp == "d") {
        vFrom = $c.ut.cGetMinusDate2(vTo, eval(sTerm));
    } else if (sTp == "m") {
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), eval(sTerm));
    } else if (sTp == "y") {
        vFrom = $c.ut.cGetMinusYear(vTo, eval(sTerm));
    } else {
        vFrom = $c.ut.cGetMinusYear(vTo, 1);
    }
    scwin.setObjectValue(pObjFrom, vFrom);
    scwin.setObjectValue(pObjTo, vTo);
};
