    var gDutyTimeYn = 'Y';
    var gNowDutyYn = ''; //현재시점 당번여부
    var gNowDutyStat = ''; //현재시점 당번상태 S:개시, E:마감, N:null
    var gProcsYn = '';
    var gTeamSameYn = '';

    //alert('[pDuty]='+pDuty+',[pDutyChrg]='+pDutyChrg+',[pDepCd]='+pDepCd)

    if (pDepCd == '2600' || //유가 공시부(당번계정)
        pDepCd == '2620' || //유가 공시1팀
        pDepCd == '2630' || //유가 공시2팀
        pDepCd == '2640' || //유가 공시3팀
