        if (pJobtitl == '09' || pJobtitl == '40') {
            //alert('pJobtitl.'+pJobtitl);

        } else {
            scwin.fn_checkDutyTimeStatus(pEmpNo, pAcptNo, pDtsObj);
            gNowDutyYn = pDtsObj.getCellData(1, 'NOW_DUTY_YN'); //현재시점 당번여부
            gNowDutyStat = pDtsObj.getCellData(1, 'NOW_DUTY_STAT'); //현재시점 당번상태 S:개시, E:마감, N:미등록
            gProcsYn = pDtsObj.getCellData(1, 'PROCS_YN');
            gTeamSameYn = pDtsObj.getCellData(1, 'TEAM_SAME_YN');
            if (gProcsYn == 'N') {
                if (gNowDutyYn == 'Y' || pDuty == 'Y' || pDutyChrg == 'Y') {
                    if (gNowDutyYn == 'Y') {
                        if (gNowDutyStat == 'S') {

                        } else {
                            if (pScrnTpCd == 'M' || gTeamSameYn != 'Y') {
                                //책임자승인에서는 개시상태가 아니면 담당종목도 조회불가
                                gDutyTimeYn = 'N';
                                alert('[당번업무 시작 권한 부여] 후에 공시조회/처리를 하실 수 있습니다.');
                            }
                        }
                    } else {
                        if (gTeamSameYn != 'Y') {
                            gDutyTimeYn = 'N';
                            alert('[당번업무]가 종료되었습니다.');
                        }
                    }
                }
            }
        }

        /*
        alert('[pJobtitl]='+pJobtitl+','  
        +'\n\r[gDutyYn]='+gNowDutyYn+',' 
        +'\n\r[gNowDutyStat]='+gNowDutyStat+','  
        +'\n\r[gProcsStatCd]='+gProcsYn+','  
        +'\n\r[gTeamSameYn]='+gTeamSameYn+','
        +'\n\r[gDutyTimeYn]='+gDutyTimeYn);
        */
