/*
 * <pre>
 * 한글을 포함한 글자의 사이즈를 구하기 위한 함수.
 *
 * 1. 설 명
 *
 * 2. 특이사항
 *    
 * </pre>
 */
/**
 * @method
 * @name getStringSize
 * @description desc
 * @param {string} message desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getStringSize = function(message) {
    var i, len = 0;
    for (i = 0; i < message.length; i++) {
        (message.charCodeAt(i) > 255) ? len += 2: len++;
    }
    return len;
};


