/**
 * @method
 * @name setButtonSetWithDate
 * @description desc
 * @param {string} obj desc
 * @param {string} includeCurDate desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setButtonSetWithDate = function(obj, includeCurDate) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");

    //	buttonSet.setUpdateStatus(); 
    //		return ;

    if (scwin.getObjectValue(obj) == "") {
        buttonSet.setUpdateStatus();
        return;
    } else if (includeCurDate) {
        if (vCurDate > scwin.getObjectValue(obj)) {
            buttonSet.setErrorStatus();
        } else {
            buttonSet.setUpdateStatus();
        }
    } else {
        if (vCurDate >= scwin.getObjectValue(obj)) {
            buttonSet.setErrorStatus();
        } else {
            buttonSet.setUpdateStatus();
        }
    }
};




