/*
 * <pre>
 * max length 체크하기 위한 함수.
 *
 *	obj  : 체크하고자하는 object
 *  size : max length
 *  lbl  : 체크하고자 하는 항목의 label
 *    
 * </pre>
 */
/**
 * @method
 * @name checkMaxLength
 * @description desc
 * @param {string} obj desc
 * @param {string} size desc
 * @param {string} lbl desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkMaxLength = function(obj, size, lbl) {
    var overLen = eval(scwin.getStringSize(scwin.getObjectValue(obj)) - size);
    if (overLen > 0) {
        alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};


