/**
 * @method
 * @name fn_GetByte
 * @description desc
 * @param {string} _obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_GetByte = function(_obj) {
    var sTmpCntnt = new String(_obj.getValue()); // 내용 저장 변수

    var iCounts = 0; // 바이트 수 저장 변수

    for (var i = 0; i < sTmpCntnt.length; i++) {
        //  16 진수 변환
        var escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar == '%0D') {
            // enter 처리
            inc = 1;
        } else if (escapeChar.length > 4) {
            // 한글 2byte 처리
            iCounts += 2;
        } else {
            iCounts++;
        }
    }
    return iCounts;
};


