/*
	srcUrl과 찾을 id를 넘겨 값을 리턴 받는다.
	getQuery(frame.srcUrl, "ISUR_CD") => 00123;
*/
/**
 * @method
 * @name getQuery
 * @description desc
 * @param {string} srcUrl desc
 * @param {string} id desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getQuery = function(srcUrl, id) {
    if (srcUrl.indexOf("?") < 0) return "";
    var queryStr = srcUrl.split("?")[1];
    var val = queryStr.split("&");
    for (var i = 0; i < val.length; i++) {
        var tmp = val[i].split("=");
        if (id == tmp[0]) {
            return tmp[1];
        }
    }
    return "";
};



/**
 * 컴마찍기
 */
/**
 * @method
 * @name addComma
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.addComma = function(str) {
    var len = str.length;
    var s1 = "",
        s2 = "";
    if (len <= 3) {
        return str;
    } else {
        for (i = len - 1; i >= 0; i--) s1 += str.charAt(i);
        for (i = len - 1; i >= 0; i--) {
            s2 += s1.charAt(i);
            if (i % 3 == 0 && i != 0) s2 += ",";
        }
        return s2;
    }
};



/*  '-145,123' 값에 대한 comma 찍기
 *  2010.03.29 - 안내문작성 시 변경주식수에 적용
 */
/**
 * @method
 * @name addCommaMinus
 * @description desc
 * @param {string} v1 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.addCommaMinus = function(v1) {
    if (v1 == "") return '';
    var v2 = 3;
    var v3 = "";
    var str = new Array();
    v1 = String(v1);
    if (v1.indexOf("-") > -1) {
        v3 = v1.substring(0, v1.indexOf("-") + 1);
        v1 = v1.substring(v1.indexOf("-") + 1, v1.length);
    }
    for (var i = 1; i <= v1.length; i++) {
        if (i % v2 == 0 && i != v1.length) {
            str[v1.length - i] = ',' + v1.charAt(v1.length - i);
        } else {
            str[v1.length - i] = v1.charAt(v1.length - i);
        }
    }
    str = str.join('').replace(/^,/, '');
    str = v3 + str;
    return str;
};



